    this.onPatchSelect = onPatchSelect;
    this.onAudition = onAudition;
    this.onWhyUpdate = onWhyUpdate;
    this.activePatchId = "monster_growl";
    this.gesture = structuredClone(GESTURE_BADGES[0].gesture);
