            relational: {
              anchor: "chord_tone",
              chord_tone_index: step2 % 4 === 0 ? 0 : 1,
              scale_degree_offset: 0,
              octave_offset: patch.id === "laser_screech" || patch.id === "vocal_chop" ? 1 : 0
            },
            gesture: structuredClone(this.sculptor.gesture)
